def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        main = {}
        other = {}
        main_tx = False
        other_tx = False
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0
        log_count = 0

        def do_put(conn, key, value):
            nonlocal main_changes, other_changes, main_total, other_total, log_count
            if conn == "main":
                changes = 0
                if put_mode == "ignore":
                    if key not in main:
                        main[key] = value
                        changes = 1
                elif put_mode == "replace":
                    main[key] = value
                    changes = 1
                else:
                    if key in main:
                        main[key] = value
                        changes = 1
                    else:
                        main[key] = value
                        changes = 1
                main_changes = changes
                main_total += changes
                if trigger and changes > 0:
                    log_count += 1
                    main_total += 1
            else:
                changes = 0
                if put_mode == "ignore":
                    if key not in other:
                        other[key] = value
                        changes = 1
                elif put_mode == "replace":
                    other[key] = value
                    changes = 1
                else:
                    if key in other:
                        other[key] = value
                        changes = 1
                    else:
                        other[key] = value
                        changes = 1
                other_changes = changes
                other_total += changes
                if trigger and changes > 0:
                    log_count += 1
                    other_total += 1

        def do_update(conn, key, value):
            nonlocal main_changes, other_changes, main_total, other_total, log_count
            if conn == "main":
                changes = 0
                if key in main:
                    main[key] = value
                    changes = 1
                main_changes = changes
                main_total += changes
                if trigger and changes > 0:
                    log_count += 1
                    main_total += 1
            else:
                changes = 0
                if key in other:
                    other[key] = value
                    changes = 1
                other_changes = changes
                other_total += changes
                if trigger and changes > 0:
                    log_count += 1
                    other_total += 1

        def do_delete(conn, key):
            nonlocal main_changes, other_changes, main_total, other_total, log_count
            if conn == "main":
                changes = 0
                if key in main:
                    del main[key]
                    changes = 1
                main_changes = changes
                main_total += changes
                if trigger and changes > 0:
                    log_count += 1
                    main_total += 1
            else:
                changes = 0
                if key in other:
                    del other[key]
                    changes = 1
                other_changes = changes
                other_total += changes
                if trigger and changes > 0:
                    log_count += 1
                    other_total += 1

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_put(conn, act["key"], act["value"])
            elif op == "update":
                do_update(conn, act["key"], act["value"])
            elif op == "delete":
                do_delete(conn, act["key"])
            elif op == "begin":
                if conn == "main":
                    main_tx = True
                else:
                    other_tx = True
            elif op == "commit":
                if conn == "main":
                    main_tx = False
                else:
                    other_tx = False
            elif op == "rollback":
                if conn == "main":
                    main_tx = False
                else:
                    other_tx = False

        if channel_mode == "main_changes":
            channel = main_changes
        elif channel_mode == "main_total":
            channel = main_total
        else:
            channel = main_total + other_total

        committed = {}
        committed.update(main)
        committed.update(other)
        count = len(committed)
        total = sum(committed.values())
        return channel, count, total

    def check(put_mode, trigger, channel_mode):
        for rec in history:
            actions = rec["actions"]
            obs = rec["observed"]
            ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
            if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                return False
        return True

    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for trigger in [False, True]:
            for channel_mode in ["main_changes", "main_total", "both_total"]:
                if check(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cnt)
        elif goal == "committed_sum":
            results.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}
